def write(path, source):
    source=textwrap.dedent(source).lstrip()
    ast.parse(source, filename=str(path))
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(source, encoding="utf-8", newline="\n")
    os.replace(tmp, path)

def main():
    print("="*100)
    print(" OAD-101 REBUILD INSTALLER")
    print(" "+TITLE)
    print("="*100)
    print("[BOOT] Revision:", REVISION)
    print("[ROOT]", ROOT)

    for rel,label in REQUIRED:
        p=ROOT/rel
        if not p.is_file():
            raise RuntimeError(label+" missing")
        print("[PASS]", label, "verified")

    frozen={ROOT/rel:hashlib.sha256((ROOT/rel).read_bytes()).hexdigest() for rel,_ in FROZEN}
    old={p:(p.read_bytes() if p.exists() else None) for p in (MODULE,TEST,INIT)}

    try:
        write(MODULE, MODULE_SOURCE)
        write(TEST, TEST_SOURCE)

        lines=INIT.read_text(encoding="utf-8").splitlines() if INIT.exists() else []
        export="from .oad_101_universal_classification_exhaustive_diagnostic import *"
        if export not in lines:
            lines.append(export)
        write(INIT, "\n".join(x for x in lines if x.strip())+"\n")

        for p,h in frozen.items():
            if hashlib.sha256(p.read_bytes()).hexdigest()!=h:
                raise RuntimeError("Frozen dependency changed: "+p.name)

        print("[PASS] Replaced foundational OAD-101 diagnostic in place")
        print("[PASS] Leg-local, parent-context, and sibling evidence now isolated")
        print("[PASS] Sibling evidence cannot directly classify another leg")
        print("[PASS] Conflicting context remains explicit")
        print("[PASS] Frozen Kalshi/OPH/UMD boundaries unchanged")
        print("[PASS] probability_enabled=FALSE")
        print("[PASS] execution_authority=FALSE")
        print("[DONE] OAD-101 CONTEXT-ISOLATION REBUILD INSTALLATION COMPLETE")
    except Exception:
        for p,data in old.items():
            if data is None:
                if p.exists():
                    p.unlink()
            else:
                p.write_bytes(data)
        print("[ROLLBACK] OAD-101 affected files restored")
        raise

if __name__=="__main__":
    main()
